    {
      "title": "Missing Email Security Records (SPF and DMARC)",
      "severity": "high",
      "context": "Your domain lacks an SPF record — an email setting that tells other mail servers which senders are authorized to send on your behalf. Without SPF and DMARC records, attackers can impersonate your domain to send convincing fake emails to clients."
    },
    {
      "title": "High-Severity Exploited Flaws in ExampleChart EHR and ExampleFiles NAS",
      "severity": "high",
      "context": "High-severity security flaws in ExampleChart EHR and ExampleFiles NAS are actively being exploited by attackers in the wild, which could put your stored files and records at risk."
    }
  ],
  "data_gaps": [
    {
      "gap_type": "Multi-Factor Authentication (MFA) Status",
      "impact": "It is unknown whether MFA — an extra login step like a text code or app prompt — is required for all users, leaving login security unverified."
    },
    {
      "gap_type": "Data Classification Policy Status",
      "impact": "It is unconfirmed whether a formal policy for handling and protecting sensitive client data is currently in place."
    },
    {
      "gap_type": "Annual Revenue Missing",
