  ],
  "next_steps": [
    {
      "priority": 1,
      "action": "Instruct your IT provider to require immediate password resets for all exposed accounts and confirm that MFA (multi-factor authentication) is turned on for every user.",
      "rationale": "Six accounts associated with your domain were leaked in public data breaches, leaving your organization vulnerable to credential-based attacks."
    },
    {
      "priority": 2,
      "action": "Ask your IT provider to apply urgent software updates to ExamplePayroll, ExampleChart EHR, and ExampleFiles NAS.",
      "rationale": "These specific products contain security flaws that attackers are actively exploiting in the wild."
    },
    {
      "priority": 3,
      "action": "Request that your IT provider or email host set up SPF and DMARC security records for your domain.",
